begin{array}{l}
11{{\$ }}25 to frac{{( {11 + 25} )}}{2} = 36/2 = 18\\
12{{\$ }}20 to frac{{( {12 + 20} )}}{2} = 32/2 = 16
end{array}

Similarly,

4\$ 50 to frac{{( {4 + 50} )}}{2} = 54/2 = 27

